// Тикет #39f5e7d5 · 39f5e7d526d0174d1709d34a (S-17, Figma 450:3687) — עבר QA 14.10.2026 (iPhone, TestFlight 1.0.0 (20)).
// Кейс .qa/tests/guided-prayer/GP-10-ashrei-lines-no-overlap.md.
// מה רצוי: «בכרטיס הקטע מוצג טקסט התפילה בשורות נפרדות, כל שורה מתחת לקודמתה, עם רווח בין השורות וללא חפיפה. כל האותיות והניקוד קריאים.»
// Факт 14.10: «מנחה (אשכנזי)» → «1 מתוך 8», קטע «אשרי» — строки не накладываются, до конца отрывка (39f5e7d5-ios-b20-mincha-ashrei-lines.png, -scrolled.png).
// Автоматически: рамки соседних строк с ניקוד не пересекаются по вертикали (если строки — отдельные элементы).
// Если весь отрывок — один текстовый элемент, наложение глифов через accessibility не видно → @manual-check по скрину.
import { driver, expect } from '@wdio/globals';
import { byText, swipeUp, pageCounter } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { visibleTexts } from '../_lib/app-1410.ts';

const NIQQUD = /[ְ-ׇ]/;

/** Видимые строки текста молитвы (с ניקוד) ниже бейджа «אשרי» и выше нижней навигации; проверка — без вертикального наложения. */
async function checkLinesNoOverlap(where: string): Promise<number> {
  const { height } = await driver.getWindowSize();
  const lines = (await visibleTexts((l, r) => NIQQUD.test(l) && r.y > 120 && r.y + r.height < height * 0.87))
    .sort((a, b) => a.r.y - b.r.y);
  if (lines.length === 0) throw new Error(`${where}: не найден текст молитвы с ניקוד`);
  if (lines.length === 1) {
    console.log(`[GP-10] ${where}: отрывок — один текстовый элемент (${Math.round(lines[0].r.height)} pt) — @manual-check наложения по скрину`);
    return 1;
  }
  for (let i = 1; i < lines.length; i++) {
    const a = lines[i - 1].r; const b = lines[i].r;
    const xOverlap = Math.min(a.x + a.width, b.x + b.width) - Math.max(a.x, b.x) > 0;
    if (!xOverlap) continue;
    // строка ниже предыдущей, без наложения (допуск 2 pt)
    const overlap = Math.max(0, Math.round(a.y + a.height - 2 - b.y));
    expect({ where, line: i, overlap }).toEqual({ where, line: i, overlap: 0 });
  }
  return lines.length;
}

describe('Строки молитвы без наложения (#39f5e7d5)', () => {
  afterEach(async () => { await toHome().catch(() => {}); });

  it('GP-10 «מנחה (אשכנזי)» → «אשרי»: строки с ניקוד одна под другой, без наложения, до конца отрывка #39f5e7d5 @prod-safe @manual-check', async () => {
    await openPrayer('mincha_ashkenaz', 'מנחה');
    await expect(byText('מנחה (אשכנזי)')).toBeDisplayed({ wait: 15000 });
    const total = Number((await pageCounter()).split(' ').pop());
    await goToPage(1, total);
    await expect(byText('אשרי')).toBeDisplayed({ wait: 10000 });

    await checkLinesNoOverlap('начало');
    for (let i = 1; i <= 5; i++) {
      await swipeUp();
      await checkLinesNoOverlap(`прокрутка ${i}`);
      if (await byText('המשך').isDisplayed().catch(() => false)) break;   // дошли до кнопок внизу — отрывок пройден
    }
  });
});
